-- 20261113090000_security_and_atomic_sessions.sql
-- Apply after the existing migrations. All changes are transactional.

CREATE OR REPLACE FUNCTION public.can_access_athlete(p_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT auth.uid() IS NOT NULL AND (
    auth.uid() = p_id OR public.es_admin(auth.uid()) OR EXISTS (
      SELECT 1 FROM public.profiles p JOIN public.profiles coach ON coach.id = auth.uid()
      WHERE p.id = p_id AND p.entrenador_id = coach.id AND coach.rol = 'entrenador'
    )
  );
$$;
REVOKE ALL ON FUNCTION public.can_access_athlete(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_access_athlete(uuid) TO authenticated;

-- Restrictive policies are ANDed with legacy policies, so a forgotten broad
-- permissive policy cannot grant cross-coach access. Subscription gates remain.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['sesiones_historial','planes','valoraciones_antropometricas','planes_nutricionales'] LOOP
    IF to_regclass('public.' || t) IS NOT NULL THEN
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
      EXECUTE format('DROP POLICY IF EXISTS account_isolation ON public.%I', t);
      EXECUTE format('CREATE POLICY account_isolation ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.can_access_athlete(cliente_id)) WITH CHECK (public.can_access_athlete(cliente_id))', t);
    END IF;
  END LOOP;
END $$;

DROP POLICY IF EXISTS account_isolation ON public.sesiones_ejercicios;
CREATE POLICY account_isolation ON public.sesiones_ejercicios AS RESTRICTIVE FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.sesiones_historial h WHERE h.id = sesion_id AND public.can_access_athlete(h.cliente_id)))
  WITH CHECK (EXISTS (SELECT 1 FROM public.sesiones_historial h WHERE h.id = sesion_id AND public.can_access_athlete(h.cliente_id)));
DROP POLICY IF EXISTS account_isolation ON public.dias_plan;
CREATE POLICY account_isolation ON public.dias_plan AS RESTRICTIVE FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.planes p WHERE p.id = plan_id AND public.can_access_athlete(p.cliente_id)))
  WITH CHECK (EXISTS (SELECT 1 FROM public.planes p WHERE p.id = plan_id AND public.can_access_athlete(p.cliente_id)));
DROP POLICY IF EXISTS account_isolation ON public.ejercicios_plan;
CREATE POLICY account_isolation ON public.ejercicios_plan AS RESTRICTIVE FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.dias_plan d JOIN public.planes p ON p.id = d.plan_id WHERE d.id = dia_id AND public.can_access_athlete(p.cliente_id)))
  WITH CHECK (EXISTS (SELECT 1 FROM public.dias_plan d JOIN public.planes p ON p.id = d.plan_id WHERE d.id = dia_id AND public.can_access_athlete(p.cliente_id)));

-- Restrict existing profile grants as well as future grants.
-- Avoid recursive RLS lookups through a small security-definer helper.
CREATE OR REPLACE FUNCTION public.my_trainer_id() RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT entrenador_id FROM public.profiles WHERE id = auth.uid();
$$;
REVOKE ALL ON FUNCTION public.my_trainer_id() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.my_trainer_id() TO authenticated;
DROP POLICY IF EXISTS profile_read_isolation ON public.profiles;
CREATE POLICY profile_read_isolation ON public.profiles AS RESTRICTIVE FOR SELECT TO authenticated
  USING (public.can_access_athlete(id) OR id = public.my_trainer_id());
DROP POLICY IF EXISTS profile_write_isolation ON public.profiles;
CREATE POLICY profile_write_isolation ON public.profiles AS RESTRICTIVE FOR UPDATE TO authenticated
  USING (public.can_access_athlete(id)) WITH CHECK (public.can_access_athlete(id));
DROP POLICY IF EXISTS profile_insert_isolation ON public.profiles;
CREATE POLICY profile_insert_isolation ON public.profiles AS RESTRICTIVE FOR INSERT TO authenticated
  WITH CHECK (public.es_admin(auth.uid()));

-- Row permissions alone do not protect sensitive columns. SECURITY INVOKER is
-- deliberate: trusted service/RPC updates execute with the definer's DB role.
CREATE OR REPLACE FUNCTION public.protect_profile_privileges() RETURNS trigger
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF current_user IN ('postgres', 'supabase_admin', 'service_role') OR public.es_admin(auth.uid()) THEN RETURN NEW; END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.rol IS DISTINCT FROM OLD.rol
    OR NEW.entrenador_id IS DISTINCT FROM OLD.entrenador_id
    OR NEW.suscripcion_plan IS DISTINCT FROM OLD.suscripcion_plan
    OR NEW.suscripcion_estado IS DISTINCT FROM OLD.suscripcion_estado
    OR NEW.suscripcion_expira_at IS DISTINCT FROM OLD.suscripcion_expira_at
    OR (OLD.id = auth.uid() AND (NEW.vigencia_dias IS DISTINCT FROM OLD.vigencia_dias OR NEW.fecha_inicio IS DISTINCT FROM OLD.fecha_inicio))
    OR NEW.onboarding_completado IS DISTINCT FROM OLD.onboarding_completado THEN
    RAISE EXCEPTION 'Los permisos y la suscripción solo pueden actualizarse mediante operaciones autorizadas' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS protect_profile_privileges ON public.profiles;
CREATE TRIGGER protect_profile_privileges BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profile_privileges();

CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE requested_role text := new.raw_user_meta_data->>'rol'; coach_id uuid;
BEGIN
  IF requested_role NOT IN ('cliente', 'entrenador') OR requested_role IS NULL THEN requested_role := 'cliente'; END IF;
  -- A self-service invitation may only target a genuine coach, never an admin.
  IF requested_role = 'cliente' AND nullif(new.raw_user_meta_data->>'entrenador_id', '') IS NOT NULL THEN
    SELECT id INTO coach_id FROM public.profiles WHERE id = (new.raw_user_meta_data->>'entrenador_id')::uuid AND rol = 'entrenador';
    IF coach_id IS NULL THEN RAISE EXCEPTION 'Invitación de entrenador no válida'; END IF;
  END IF;
  INSERT INTO public.profiles (id, email, nombre, rol, objetivo, vigencia_dias, entrenador_id, modalidad, onboarding_completado)
  VALUES (new.id, new.email, coalesce(nullif(new.raw_user_meta_data->>'nombre', ''), 'Nuevo Atleta'), requested_role,
    new.raw_user_meta_data->>'objetivo', 30, coach_id,
    CASE WHEN new.raw_user_meta_data->>'modalidad' = 'presencial' THEN 'presencial' ELSE 'remoto' END,
    coalesce(new.raw_user_meta_data->>'rol' IN ('cliente', 'entrenador'), false));
  RETURN new;
END $$;

CREATE OR REPLACE FUNCTION public.complete_role_selection(p_rol text, p_nombre text DEFAULT NULL, p_whatsapp text DEFAULT '', p_instagram text DEFAULT '')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE result jsonb;
BEGIN
  IF auth.uid() IS NULL OR p_rol IS NULL OR p_rol NOT IN ('cliente', 'entrenador') THEN RAISE EXCEPTION 'Operación no autorizada' USING ERRCODE = '42501'; END IF;
  PERFORM 1 FROM public.profiles WHERE id = auth.uid() AND onboarding_completado = false FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'La selección inicial de rol ya está completada'; END IF;
  UPDATE public.profiles SET rol = p_rol, nombre = coalesce(nullif(trim(p_nombre), ''), nombre), onboarding_completado = true,
    marca = CASE WHEN p_rol = 'entrenador' THEN coalesce(marca, '{}'::jsonb) || jsonb_build_object('nombre_display', p_nombre, 'whatsapp', p_whatsapp, 'instagram', p_instagram) ELSE marca END
  WHERE id = auth.uid();
  SELECT to_jsonb(p) INTO result FROM public.profiles p WHERE id = auth.uid();
  RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.complete_role_selection(text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.complete_role_selection(text,text,text,text) TO authenticated;

-- Public discovery returns presentation fields, never email or subscription data.
CREATE OR REPLACE FUNCTION public.trainer_directory(p_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', id, 'nombre', nombre, 'marca', marca, 'logo_url', logo_url, 'filosofia', filosofia)), '[]'::jsonb)
  FROM public.profiles WHERE rol = 'entrenador' AND (p_id IS NULL OR id = p_id);
$$;
REVOKE ALL ON FUNCTION public.trainer_directory(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.trainer_directory(uuid) TO anon, authenticated;

-- One transaction and one stable key for both offline and online recordings.
ALTER TABLE public.sesiones_historial ADD COLUMN IF NOT EXISTS client_operation_id text;
ALTER TABLE public.sesiones_ejercicios ADD COLUMN IF NOT EXISTS client_exercise_index integer;
CREATE UNIQUE INDEX IF NOT EXISTS sesiones_operation_unique ON public.sesiones_historial(cliente_id, client_operation_id);
CREATE OR REPLACE FUNCTION public.record_training_session(p_cliente_id uuid, p_operation_id text, p_session jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
DECLARE session_id uuid; exercises jsonb;
BEGIN
  IF NOT public.can_access_athlete(p_cliente_id) OR p_operation_id IS NULL OR length(trim(p_operation_id)) NOT BETWEEN 1 AND 160 THEN
    RAISE EXCEPTION 'Operación no autorizada' USING ERRCODE = '42501';
  END IF;
  IF jsonb_typeof(p_session->'ejercicios') IS DISTINCT FROM 'array' OR jsonb_array_length(p_session->'ejercicios') NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'La sesión debe contener entre 1 y 200 ejercicios';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cliente_id::text || ':' || p_operation_id, 0));
  SELECT id INTO session_id FROM public.sesiones_historial WHERE cliente_id = p_cliente_id AND client_operation_id = p_operation_id;
  IF session_id IS NULL THEN
    INSERT INTO public.sesiones_historial(cliente_id, fecha, notas_generales, express_mode, express_blocks, client_operation_id)
    VALUES (p_cliente_id, (p_session->>'fecha')::date, p_session->>'notas_sesion', coalesce((p_session->>'express_mode')::boolean, false), coalesce(p_session->'express_blocks', '[]'::jsonb), p_operation_id)
    RETURNING id INTO session_id;
    INSERT INTO public.sesiones_ejercicios(sesion_id, nombre_ejercicio, grupo_muscular, series_reps, peso, rpe_rir, descanso, volumen, rm_estimado, feedback_estimulo, feedback_recuperacion, client_exercise_index)
    SELECT session_id, e->>'nombre_ejercicio', e->>'grupo_muscular', e->'series_reps', (e->>'peso')::numeric, (e->>'rpe_rir')::numeric,
      (e->>'descanso')::integer, (e->>'volumen')::numeric, (e->>'rm_estimado')::numeric, e->>'feedback_estimulo', e->>'feedback_recuperacion', ordinal::integer
    FROM jsonb_array_elements(p_session->'ejercicios') WITH ORDINALITY AS entries(e, ordinal);
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id_ej', id, 'nombre', nombre_ejercicio) ORDER BY client_exercise_index), '[]'::jsonb) INTO exercises FROM public.sesiones_ejercicios WHERE sesion_id = session_id;
  RETURN jsonb_build_object('id', session_id, 'ejercicios', exercises);
END $$;
REVOKE ALL ON FUNCTION public.record_training_session(uuid,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_training_session(uuid,text,jsonb) TO authenticated;

-- 20261113090100_payment_ledger.sql
CREATE TABLE IF NOT EXISTS public.payment_ledger (
  payment_id text PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES public.profiles(id),
  plan text NOT NULL CHECK (plan IN ('premium','iniciacion','intermedio','profesional')),
  status text NOT NULL,
  approved_at timestamptz,
  updated_at timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS payment_ledger_user ON public.payment_ledger(user_id, approved_at);
ALTER TABLE public.payment_ledger ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.payment_ledger FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON public.payment_ledger TO service_role;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS billing_payment_id text;

CREATE OR REPLACE FUNCTION public.apply_verified_payment(p_payment_id text, p_user_id uuid, p_plan text, p_status text, p_approved_at timestamptz, p_updated_at timestamptz)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE previous public.payment_ledger; item public.payment_ledger; expires timestamptz; latest public.payment_ledger; managed text;
BEGIN
  IF p_status NOT IN ('approved','refunded','charged_back','cancelled','rejected','pending','in_process','authorized','in_mediation') OR p_updated_at IS NULL
    OR p_plan NOT IN ('premium','iniciacion','intermedio','profesional') OR (p_status = 'approved' AND p_approved_at IS NULL) THEN RAISE EXCEPTION 'Pago no válido'; END IF;
  -- Serializes all payments for one account, including different payment IDs.
  SELECT billing_payment_id INTO managed FROM public.profiles WHERE id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Perfil de pago no encontrado'; END IF;
  SELECT * INTO previous FROM public.payment_ledger WHERE payment_id = p_payment_id;
  IF FOUND AND (previous.user_id <> p_user_id OR previous.plan <> p_plan) THEN RAISE EXCEPTION 'Identidad de pago incompatible'; END IF;
  IF previous.updated_at IS NOT NULL AND previous.updated_at >= p_updated_at THEN RETURN jsonb_build_object('updated', false, 'duplicate', true); END IF;
  INSERT INTO public.payment_ledger VALUES (p_payment_id, p_user_id, p_plan, p_status, p_approved_at, p_updated_at)
  ON CONFLICT(payment_id) DO UPDATE SET status = excluded.status, approved_at = excluded.approved_at, updated_at = excluded.updated_at;
  -- Deterministic reconciliation: delivery order does not change entitlement.
  -- Each approved purchase adds 30 days; refunded purchases contribute nothing.
  FOR item IN SELECT * FROM public.payment_ledger WHERE user_id = p_user_id AND status = 'approved' ORDER BY approved_at, payment_id LOOP
    expires := greatest(coalesce(expires, item.approved_at), item.approved_at) + interval '30 days';
    latest := item;
  END LOOP;
  IF latest.payment_id IS NOT NULL THEN
    UPDATE public.profiles SET suscripcion_plan = latest.plan,
      suscripcion_estado = CASE WHEN expires > now() THEN 'activo' ELSE 'expirado' END,
      suscripcion_expira_at = expires, billing_payment_id = latest.payment_id WHERE id = p_user_id;
    IF latest.plan = 'premium' THEN
      INSERT INTO public.suscripciones(cliente_id, tipo, estado, fecha_inicio, fecha_expiracion)
      VALUES(p_user_id, 'premium', CASE WHEN expires > now() THEN 'activa' ELSE 'expirada' END, latest.approved_at, expires)
      ON CONFLICT(cliente_id) DO UPDATE SET tipo = excluded.tipo, estado = excluded.estado, fecha_inicio = excluded.fecha_inicio, fecha_expiracion = excluded.fecha_expiracion;
    ELSE
      UPDATE public.suscripciones SET estado = 'cancelada' WHERE cliente_id = p_user_id;
    END IF;
  ELSIF managed IS NOT NULL THEN
    UPDATE public.profiles SET suscripcion_plan = 'free', suscripcion_estado = 'cancelado', suscripcion_expira_at = now(), billing_payment_id = NULL WHERE id = p_user_id;
    UPDATE public.suscripciones SET estado = 'cancelada', fecha_expiracion = now() WHERE cliente_id = p_user_id;
  END IF;
  RETURN jsonb_build_object('updated', true, 'duplicate', false);
END $$;
REVOKE ALL ON FUNCTION public.apply_verified_payment(text,uuid,text,text,timestamptz,timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.apply_verified_payment(text,uuid,text,text,timestamptz,timestamptz) TO service_role;

-- Billing provenance is just as sensitive as plan and role.
CREATE OR REPLACE FUNCTION public.protect_billing_provenance() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF NEW.billing_payment_id IS DISTINCT FROM OLD.billing_payment_id AND current_user NOT IN ('postgres','supabase_admin','service_role') AND NOT public.es_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Campo de facturación protegido' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS protect_billing_provenance ON public.profiles;
CREATE TRIGGER protect_billing_provenance BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_billing_provenance();

-- 20261113090200_coach_invitations.sql
CREATE OR REPLACE FUNCTION public.assert_trainer_capacity(p_coach uuid, p_modality text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE coach public.profiles; total int; same_modality int; max_clients int;
BEGIN
  SELECT * INTO coach FROM public.profiles WHERE id = p_coach AND rol = 'entrenador' FOR UPDATE;
  IF NOT FOUND OR coach.suscripcion_estado IN ('expirado','cancelado') OR coach.suscripcion_expira_at < now() THEN RAISE EXCEPTION 'La membresía del entrenador no está disponible'; END IF;
  SELECT count(*), count(*) FILTER (WHERE modalidad = p_modality) INTO total, same_modality FROM public.profiles WHERE entrenador_id = p_coach;
  max_clients := CASE coach.suscripcion_plan WHEN 'profesional' THEN 2147483647 WHEN 'intermedio' THEN 10 WHEN 'iniciacion' THEN 2 ELSE 2 END;
  IF total >= max_clients OR (coalesce(coach.suscripcion_plan,'free') = 'free' AND same_modality >= 1) THEN RAISE EXCEPTION 'El entrenador ha alcanzado el límite de atletas de su plan'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.assert_trainer_capacity(uuid,text) FROM PUBLIC, anon, authenticated;

-- Defense in depth for all signup entry points, not only the login form.
CREATE OR REPLACE FUNCTION public.check_new_athlete_capacity() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NEW.entrenador_id IS NOT NULL THEN PERFORM public.assert_trainer_capacity(NEW.entrenador_id, NEW.modalidad); END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS check_new_athlete_capacity ON public.profiles;
CREATE TRIGGER check_new_athlete_capacity BEFORE INSERT ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.check_new_athlete_capacity();

CREATE OR REPLACE FUNCTION public.trainer_invitation_info(p_id uuid) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT jsonb_build_object('id',id,'nombre',nombre,'available',coalesce(suscripcion_estado NOT IN ('expirado','cancelado') AND (suscripcion_expira_at IS NULL OR suscripcion_expira_at > now()),false))
  FROM public.profiles WHERE id=p_id AND rol='entrenador';
$$;
REVOKE ALL ON FUNCTION public.trainer_invitation_info(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.trainer_invitation_info(uuid) TO anon, authenticated;

CREATE TABLE IF NOT EXISTS public.coach_invitations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  coach_id uuid NOT NULL REFERENCES public.profiles(id),
  athlete_id uuid NOT NULL REFERENCES public.profiles(id),
  modality text NOT NULL CHECK(modality IN ('remoto','presencial')),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL DEFAULT now() + interval '7 days',
  status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined')),
  UNIQUE(coach_id,athlete_id)
);
ALTER TABLE public.coach_invitations ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS invitation_participants ON public.coach_invitations;
CREATE POLICY invitation_participants ON public.coach_invitations FOR SELECT TO authenticated USING(athlete_id=auth.uid() OR coach_id=auth.uid());
REVOKE ALL ON public.coach_invitations FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.coach_invitations TO authenticated;
GRANT ALL ON public.coach_invitations TO service_role;

CREATE OR REPLACE FUNCTION public.request_coach_invitation(p_email text, p_modality text DEFAULT 'remoto') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE target uuid;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND rol='entrenador') THEN RAISE EXCEPTION 'Operación no autorizada'; END IF;
  IF p_modality NOT IN ('remoto','presencial') THEN RAISE EXCEPTION 'Modalidad no válida'; END IF;
  PERFORM public.assert_trainer_capacity(auth.uid(), p_modality);
  SELECT id INTO target FROM public.profiles WHERE lower(email)=lower(trim(p_email)) AND rol='cliente' AND entrenador_id IS NULL;
  -- Do not disclose whether an email has an account or belongs to another coach.
  IF target IS NOT NULL THEN
    INSERT INTO public.coach_invitations(coach_id,athlete_id,modality) VALUES(auth.uid(),target,p_modality)
    ON CONFLICT(coach_id,athlete_id) DO UPDATE SET status='pending', modality=excluded.modality, expires_at=now()+interval '7 days';
  END IF;
END $$;
REVOKE ALL ON FUNCTION public.request_coach_invitation(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.request_coach_invitation(text,text) TO authenticated;

CREATE OR REPLACE FUNCTION public.respond_coach_invitation(p_id uuid, p_accept boolean) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE invitation public.coach_invitations;
BEGIN
  SELECT * INTO invitation FROM public.coach_invitations WHERE id=p_id AND athlete_id=auth.uid() AND status='pending' AND expires_at > now() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invitación no disponible'; END IF;
  IF p_accept THEN
    PERFORM public.assert_trainer_capacity(invitation.coach_id, invitation.modality);
    UPDATE public.profiles SET entrenador_id=invitation.coach_id, modalidad=invitation.modality WHERE id=auth.uid() AND rol='cliente' AND entrenador_id IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'Ya tienes un entrenador vinculado'; END IF;
  END IF;
  UPDATE public.coach_invitations SET status=CASE WHEN p_accept THEN 'accepted' ELSE 'declined' END WHERE id=p_id;
END $$;
REVOKE ALL ON FUNCTION public.respond_coach_invitation(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.respond_coach_invitation(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.pending_coach_invitations() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'coach_name', p.nombre)), '[]'::jsonb)
  FROM public.coach_invitations i JOIN public.profiles p ON p.id=i.coach_id
  WHERE i.athlete_id=auth.uid() AND i.status='pending' AND i.expires_at > now();
$$;
REVOKE ALL ON FUNCTION public.pending_coach_invitations() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.pending_coach_invitations() TO authenticated;

-- 20261113090300_service_session_maintenance.sql
-- Some existing deployments grant session maintenance only to authenticated.
-- The server needs these two operations to remove session children before an
-- administrative account deletion. No browser or anonymous grant is added.

GRANT SELECT, DELETE ON TABLE public.sesiones_historial, public.sesiones_ejercicios TO service_role;

-- 20261114090000_enable_exercise_catalog_rls.sql
-- The catalog already has role-based policies, but RLS was disabled remotely.
-- Enable those policies and remove privileges that bypass RLS (e.g. TRUNCATE).
-- No exercise rows, media URLs, prices or subscription data are changed.

DO $guard$
BEGIN
  IF (SELECT count(DISTINCT cmd) FROM pg_policies
      WHERE schemaname='public' AND tablename='ejercicios_globales'
        AND cmd IN ('SELECT','INSERT','UPDATE','DELETE')) <> 4
    OR NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public'
      AND tablename='ejercicios_alias' AND cmd='SELECT') THEN
    RAISE EXCEPTION 'Faltan las políticas base del catálogo; no se cambió la configuración.';
  END IF;
END $guard$;

ALTER TABLE public.ejercicios_globales ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ejercicios_alias ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.ejercicios_globales, public.ejercicios_alias FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.ejercicios_globales, public.ejercicios_alias TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.ejercicios_globales TO authenticated;
GRANT ALL ON public.ejercicios_globales, public.ejercicios_alias TO service_role;

-- Handle a serial/identity primary key if present, without assuming its name.
DO $sequences$
DECLARE item record;
BEGIN
  FOR item IN SELECT DISTINCT ns.nspname, seq.relname
    FROM pg_class seq JOIN pg_namespace ns ON ns.oid=seq.relnamespace
    JOIN pg_depend dep ON dep.objid=seq.oid AND dep.classid='pg_class'::regclass AND dep.deptype IN ('a','i')
    JOIN pg_class tbl ON tbl.oid=dep.refobjid
    JOIN pg_namespace tn ON tn.oid=tbl.relnamespace
    WHERE seq.relkind='S' AND tn.nspname='public' AND tbl.relname='ejercicios_globales'
  LOOP
    EXECUTE format('REVOKE ALL ON SEQUENCE %I.%I FROM PUBLIC, anon, authenticated',item.nspname,item.relname);
    EXECUTE format('GRANT USAGE, SELECT ON SEQUENCE %I.%I TO authenticated',item.nspname,item.relname);
    EXECUTE format('GRANT ALL ON SEQUENCE %I.%I TO service_role',item.nspname,item.relname);
  END LOOP;
END $sequences$;

COMMIT;
